31	function arrayToList(useSpace: boolean, array: unknown[], formatter: (value: unknown) => string) {
32	  let sql = ''
33	
34	  sql += useSpace ? ' (' : '('
35	  for (const [index, element] of array.entries()) {
36	    sql += (index === 0 ? '' : ', ') + formatter(element)
