45	export function ident(value?: unknown): string {
46	  if (value === undefined || value === null) {
47	    throw new Error('SQL identifier cannot be null or undefined')
48	  } else if (value === false) {
49	    return '"f"'
50	  } else if (value === true) {
51	    return '"t"'
52	  } else if (value instanceof Date) {
53	    return `"${formatDate(value.toISOString())}"`
54	  } else if (Array.isArray(value)) {
55	    const temporary: string[] = []
56	    for (const element of value) {
57	      if (Array.isArray(element) === true) {
58	        throw new TypeError(
59	          'Nested array to grouped list conversion is not supported for SQL identifier'
60	        )
61	      } else {
62	        temporary.push(ident(element))
63	      }
64	    }
65	    return temporary.toString()
66	  } else if (value === Object(value)) {
67	    throw new Error('SQL identifier cannot be an object')
68	  }
69	
70	  const tident = String(value).slice(0) // create copy
71	
72	  // do not quote a valid, unquoted identifier
73	  if (/^[_a-z][\d$_a-z]*$/.test(tident) === true && isReserved(tident) === false) {
74	    return tident
75	  }
76	
77	  let quoted = '"'
78	
79	  for (const c of tident) {
80	    quoted += c === '"' ? c + c : c
81	  }
82	
83	  quoted += '"'
84	
85	  return quoted
86	}
