import { COLUMN_PRIVILEGES_SQL } from './sql/column-privileges'
import { z } from 'zod'

const pgColumnPrivilegesZod = z.object({
  column_id: z.string().regex(/^\d+\.\d+$/),
  relation_schema: z.string(),
  relation_name: z.string(),
  column_name: z.string(),
  privileges: z.array(
    z.object({
      grantor: z.string(),
      grantee: z.string(),
      privilege_type: z.union([
        z.literal('SELECT'),
        z.literal('INSERT'),
        z.literal('UPDATE'),
        z.literal('REFERENCES'),
      ]),
      is_grantable: z.boolean(),
    })
  ),
})
const pgColumnPrivilegesArrayZod = z.array(pgColumnPrivilegesZod)

function list({
  columnIds,
}: {
  columnIds?: string[]
} = {}): {
  sql: string
  zod: typeof pgColumnPrivilegesArrayZod
} {
  let sql = `
with column_privileges as (${COLUMN_PRIVILEGES_SQL})
select *
from column_privileges
`
  if (columnIds && columnIds.length > 0) {
    sql += ` where column_id in (${columnIds.map(literal).join(',')})`
  }
  return {
    sql,
    zod: pgColumnPrivilegesArrayZod,
  }
}

type ColumnPrivilegesGrant = {
  columnId: string
  grantee: string
  privilegeType: 'ALL' | 'SELECT' | 'INSERT' | 'UPDATE' | 'REFERENCES'
  isGrantable?: boolean
}
function grant(grants: ColumnPrivilegesGrant[]): { sql: string } {
  const sql = `
do $$
begin
${grants
  .map(({ privilegeType, columnId, grantee, isGrantable }) => {
    const [relationId, columnNumber] = columnId.split('.')
    const granteeSql = grantee.toLowerCase() === 'public' ? 'public' : ident(grantee)
    // The relation and column names are resolved from the catalog inside the
    // dynamic statement so that names with spaces or special characters are
    // quoted correctly (via `%I` for the column and `::regclass` for the relation).
    return `execute format(
  'grant ${privilegeType} (%I) on %s to ${granteeSql} ${isGrantable ? 'with grant option' : ''}',
  (select attname from pg_attribute where attrelid = ${literal(
    Number(relationId)
  )} and attnum = ${literal(Number(columnNumber))}),
  ${literal(Number(relationId))}::regclass
);`
  })
  .join('\n')}
end $$;
`
  return { sql }
}

type ColumnPrivilegesRevoke = {
  columnId: string
  grantee: string
  privilegeType: 'ALL' | 'SELECT' | 'INSERT' | 'UPDATE' | 'REFERENCES'
}
function revoke(revokes: ColumnPrivilegesRevoke[]): { sql: string } {
  const sql = `
do $$
begin
${revokes
  .map(({ privilegeType, columnId, grantee }) => {
    const [relationId, columnNumber] = columnId.split('.')
    const granteeSql = grantee.toLowerCase() === 'public' ? 'public' : ident(grantee)
    return `execute format(
  'revoke ${privilegeType} (%I) on %s from ${granteeSql}',
  (select attname from pg_attribute where attrelid = ${literal(
    Number(relationId)
  )} and attnum = ${literal(Number(columnNumber))}),
  ${literal(Number(relationId))}::regclass
);`
  })
  .join('\n')}
end $$;
`
  return { sql }
}

export default {
  list,
  grant,
  revoke,
  zod: pgColumnPrivilegesZod,
}
